const LAYOUT_OPTIONS: {
	key: string;
	name: string;
	icon: ReactElement;
}[] = [
	{ key: 'stack', name: __('Stack', 'quillforms'), icon: layoutIcons.stack },
	{ key: 'float-left', name: __('Float Left', 'quillforms'), icon: layoutIcons.floatLeft },
	{ key: 'float-right', name: __('Float Right', 'quillforms'), icon: layoutIcons.floatRight },
	{ key: 'split-left', name: __('Split Left', 'quillforms'), icon: layoutIcons.splitLeft },
	{ key: 'split-right', name: __('Split Right', 'quillforms'), icon: layoutIcons.splitRight },
];

type BlockLayoutProps = {
	layout: string | undefined;
	setAttributes: (attrs: { layout: string }) => void;
};

const BlockLayout = ({ layout, setAttributes }: BlockLayoutProps) => {
	return (
		<div className="block-editor-block-layout" role="group" aria-label={__('Layout options', 'quillforms')}>
			{LAYOUT_OPTIONS.map((option) => {
				const selected = layout === option.key;
				return (
					<button
						key={option.key}
						type="button"
						className={
							`block-editor-block-layout__option block-editor-block-layout__option--${option.key}` +
							(selected ? ' block-editor-block-layout__option--selected' : '')
						}
						aria-label={
							selected
								? sprintf(
										/* translators: %s: layout option name */
										__('%s, selected', 'quillforms'),
										option.name
									)
								: option.name
						}
						onClick={() => setAttributes({ layout: option.key })}
					>
						<span className="block-editor-block-layout__icon" aria-hidden>
							{option.icon}
						</span>
						<span className="block-editor-block-layout__label">{option.name}</span>
					</button>
				);
			})}
		</div>
	);
};

export default BlockLayout;
